// Package openapi holds the glue between an OpenAPI contract-first server
// generated by oapi-codegen (chi-server + strict-server) and vogel's request
// and response packages.
//
// The pattern it supports: api/openapi.yaml is the source of truth, the
// strict server is generated from it, and the routes are still registered by
// hand on chi so each keeps its authentication, RequirePermission and rate
// limits next to it. The generated parameter binding is bypassed (parameters
// are declared with x-go-type: string) and handlers read the request through
// Request, validating it with request.Validator, so error messages and
// envelopes stay exactly the ones vogel sends. Successes use the generated
// typed responses; errors are returned as Go errors that carry their vogel
// writer:
//
//	func (h *Handler) GetEntry(ctx context.Context, req gen.GetEntryRequestObject) (gen.GetEntryResponseObject, error) {
//	    r := openapi.Request(ctx)
//	    v := request.NewValidator()
//	    id := v.UUIDParam(r, "id")
//	    if v.HasErrors() {
//	        return nil, openapi.Invalid(v)
//	    }
//	    ...
//	}
//
// Wire the strict server with ResponseErrorHandler and RequestErrorHandler:
//
//	api := gen.NewStrictHandlerWithOptions(handlers, nil, gen.StrictHTTPServerOptions{
//	    RequestErrorHandlerFunc:  openapi.RequestErrorHandler,
//	    ResponseErrorHandlerFunc: openapi.ResponseErrorHandler(logger),
//	})
//
// The package does not import oapi-codegen: it only depends on net/http and
// vogel.
package openapi

import (
	"context"
	"errors"
	"log/slog"
	"net/http"

	"github.com/kafeiih/vogel/httpx/response"
	"github.com/kafeiih/vogel/request"
)

// writtenError is an error a strict handler returns to answer with its own
// vogel response instead of a generated typed one.
type writtenError struct {
	err   error
	write func(w http.ResponseWriter, r *http.Request)
}

func (e *writtenError) Error() string {
	if e.err == nil {
		return "request rejected"
	}
	return e.err.Error()
}

func (e *writtenError) Unwrap() error { return e.err }

// Fail returns an error that, returned from a strict handler, makes
// ResponseErrorHandler answer with write. err is the cause, kept for
// errors.Is/As; it may be nil.
func Fail(err error, write func(w http.ResponseWriter, r *http.Request)) error {
	return &writtenError{err: err, write: write}
}

// Respond returns an error answered with response.ErrorWith(status, code,
// message, opts...).
func Respond(status int, code, message string, opts ...response.ErrorOption) error {
	return Fail(nil, func(w http.ResponseWriter, r *http.Request) {
		response.ErrorWith(w, r, status, code, message, opts...)
	})
}

// Invalid returns an error answered with v's field errors (400
// VALIDATION_ERROR), logged as Validator.WriteErrors logs them.
func Invalid(v *request.Validator) error {
	return Fail(nil, v.WriteErrors)
}

// WriteError writes the response err carries, if any, and reports whether it
// did. err may wrap the error Fail returned.
func WriteError(w http.ResponseWriter, r *http.Request, err error) bool {
	var we *writtenError
	if !errors.As(err, &we) {
		return false
	}
	we.write(w, r)
	return true
}

// ResponseErrorHandler returns the strict server's ResponseErrorHandlerFunc:
// it writes the response an error from Fail, Respond or Invalid carries, and
// answers any other error with a 500 INTERNAL_ERROR, logging it to l (or
// slog.Default() when l is nil).
func ResponseErrorHandler(l *slog.Logger) func(w http.ResponseWriter, r *http.Request, err error) {
	if l == nil {
		l = slog.Default()
	}
	return func(w http.ResponseWriter, r *http.Request, err error) {
		if WriteError(w, r, err) {
			return
		}
		l.ErrorContext(r.Context(), "unhandled operation error", "error", err, "method", r.Method, "path", r.URL.Path)
		response.Error(w, r, http.StatusInternalServerError, response.CodeInternalError, "Internal server error")
	}
}

// RequestErrorHandler is the strict server's RequestErrorHandlerFunc: the
// generated decoder could not read the body, so it answers 400 INVALID_JSON
// and logs the rejection. With Decode or DecodeJSON in front of the
// operation, vogel has already rejected such bodies with its own messages.
func RequestErrorHandler(w http.ResponseWriter, r *http.Request, _ error) {
	request.LogRejection(nil, r, http.StatusBadRequest, response.CodeInvalidJSON)
	response.Error(w, r, http.StatusBadRequest, response.CodeInvalidJSON, request.DefaultMessages().InvalidBody)
}

type requestKey struct{}

// RequestInContext stores the request in its own context so strict handlers,
// which only receive a context, can read it with Request. Install it as the
// last middleware of each contract route: the stored request is the one it
// sees, so context values added after it are not in it.
func RequestInContext(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		slot := new(*http.Request)
		r = r.WithContext(context.WithValue(r.Context(), requestKey{}, slot))
		*slot = r
		next.ServeHTTP(w, r)
	})
}

// Request returns the request RequestInContext stored. A handler reached
// without that middleware is a wiring bug, so it panics instead of guessing
// (vogel's Recovery turns the panic into a 500).
func Request(ctx context.Context) *http.Request {
	slot, ok := ctx.Value(requestKey{}).(**http.Request)
	if !ok {
		panic("openapi: RequestInContext middleware is not installed")
	}
	return *slot
}

// ServeSpec serves the raw OpenAPI document as application/yaml. Serve the
// embedded file itself rather than oapi-codegen's embedded spec, which is
// re-encoded and does not keep the document byte for byte.
func ServeSpec(spec []byte) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/yaml")
		_, _ = w.Write(spec)
	})
}
